package com.estradaplay.patriota;
import android.content.Context;import android.content.SharedPreferences;import org.json.*;import java.util.*;
final class FuelingStore{private static final String P="epp_fueling_v160",K="rows";static void add(Context c,String vehicleId,double liters,double total,double odometer){try{JSONArray old=rows(c),out=new JSONArray();JSONObject o=new JSONObject();o.put("vehicle_id",vehicleId);o.put("at",System.currentTimeMillis());o.put("liters",Math.max(0,liters));o.put("total",Math.max(0,total));o.put("odometer",Math.max(0,odometer));out.put(o);for(int i=0;i<old.length()&&out.length()<60;i++)out.put(old.opt(i));c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}static JSONArray rows(Context c){try{return new JSONArray(c.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}static double actualKml(Context c,String vehicleId){JSONArray a=rows(c);JSONObject newest=null,previous=null;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null||!vehicleId.equals(o.optString("vehicle_id"))||o.optDouble("odometer",0)<=0)continue;if(newest==null)newest=o;else{previous=o;break;}}if(newest==null||previous==null)return 0;double d=newest.optDouble("odometer")-previous.optDouble("odometer"),l=newest.optDouble("liters");return d>0&&l>0?d/l:0;}}
